/// The lints clippy removed, and why: naming one is a warning of rustc's, and does nothing.
pub(super) static REMOVED: &[(&str, &str)] = &[
    (
        "assign_ops",
        "compound operators are harmless and linting on them is not in scope for clippy",
    ),
    (
        "extend_from_slice",
        "`Vec::extend_from_slice` is no longer faster than `Vec::extend` due to specialization",
    ),
    ("from_iter_instead_of_collect", "lint has proved problematic"),
    ("match_on_vec_items", "`clippy::indexing_slicing` covers indexing and slicing on `Vec<_>`"),
    (
        "misaligned_transmute",
        "split into `clippy::cast_ptr_alignment` and `clippy::transmute_ptr_to_ptr`",
    ),
    ("option_map_or_err_ok", "`clippy::manual_ok_or` covers this case"),
    (
        "pub_enum_variant_names",
        "`clippy::enum_variant_names` now covers this case via the `avoid-breaking-exported-api` config",
    ),
    (
        "range_step_by_zero",
        "`Iterator::step_by(0)` now panics and is no longer an infinite iterator",
    ),
    ("regex_macro", "the `regex!` macro was removed from the regex crate in 2018"),
    ("replace_consts", "`min_value` and `max_value` are now deprecated"),
    (
        "should_assert_eq",
        "`assert!(a == b)` can now print the values the same way `assert_eq!(a, b) can",
    ),
    ("string_to_string", "`clippy::implicit_clone` covers those cases"),
    ("unsafe_vector_initialization", "the suggested alternative could be substantially slower"),
    ("unstable_as_mut_slice", "`Vec::as_mut_slice` is now stable"),
    ("unstable_as_slice", "`Vec::as_slice` is now stable"),
    ("unused_collect", "`Iterator::collect` is now marked as `#[must_use]`"),
    (
        "wrong_pub_self_convention",
        "`clippy::wrong_self_convention` now covers this case via the `avoid-breaking-exported-api` config",
    ),
];

